import {NASA_DATA,DISTANCES,nasaValue} from '../data/nasa.js';
import {HELP_TOPICS,answerQuestion} from '../engine/assistant.js';
import {EXPERIMENT_FIELDS} from '../engine/copilot.js';
import {CATALOG,CATEGORIES,MISSION as M,PRESETS,SOURCES,UNCERTAINTY,VERSION} from '../data/catalog.js';
import {calculate,normalize,newRun,advance,resolve,runToEnd,robustness,debrief,pareto,clone,clamp,linkEnvironment} from '../engine/model.js';
import {scene} from './scene.js';
import {mountSpace3D,cameraState} from './space3d.js';
const $=s=>document.querySelector(s), fmt=(v,n=0)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:n,minimumFractionDigits:n});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='trajectiq-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{}
if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};
const validSavedRun=r=>r&&['2.0.0','3.0.0','4.0.0'].includes(r.modelVersion)&&r.done&&r.outcome&&r.design&&['completion','cost','science','returned','lostMB','safeMinutes'].every(k=>Number.isFinite(r.outcome[k]))&&['logs','events','history','seen'].every(k=>Array.isArray(r[k]));
const state={page:'game',category:'payload',design:normalize(saved.design||PRESETS.balanced),run:null,runs:(Array.isArray(saved.runs)?saved.runs:[]).filter(validSavedRun).slice(-20),playing:false,speed:1,pitch:false,robust:null,mentorLevel:'Beginner',quiz:null,guide:0,chat:[],prefs:{language:saved.prefs?.language==='bn'?'bn':'en',guided:saved.prefs?.guided!==false,reducedMotion:saved.prefs?.reducedMotion??(globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches||false)},game:{stage:'brief',fullscreen:false}};
let timer=null,toastTimer=null,lastFocus=null,spaceRenderer=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify({design:state.design,runs:state.runs,prefs:state.prefs}));}catch{toast('Browser storage unavailable. Export your mission report to keep it.');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
const button=(text,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
function heading(kicker,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
const phases=['Brief','Architecture','Readiness','Launch','Transfer','Capture','Operations','Debrief'];
function render(){
  const oldCanvas=$('#game-canvas');
  const nav=[['game','▶','Play mission'],['brief','01','Mission brief'],['architect','02','Engineering lab'],['readiness','03','Readiness review'],['control','04','Telemetry detail'],['debrief','05','Causal debrief'],['trade','06','Trade space'],['sources','07','Sources & method']];
  const content=({landing,game,brief,architect,readiness,control,debriefPage,trade,sources})[{debrief:'debriefPage'}[state.page]||state.page]();
  $('#app').innerHTML=`<header class="topbar"><a class="brand" href="#" data-action="home"><img src="./icon.svg" alt=""><div>TRAJECTIQ<span>SPACE MISSION DESIGN LAB</span></div></a><div class="top-actions"><span class="badge"><i class="online-dot"></i>LOCAL SIMULATION</span>${button('Ask mission assistant','mentor','ghost small mentor-top')}${button('Pitch mode ↗','pitch','ghost small')}</div></header>
  <div class="shell"><aside class="sidebar"><div><div class="sidebar-label">MISSION WORKSPACE</div><nav class="nav-list" aria-label="Mission screens">${nav.map(([p,n,t])=>`<button class="nav-btn ${state.page===p?'active':''}" data-page="${p}" ${state.page===p?'aria-current="page"':''}><span class="number">${n}</span>${t}</button>`).join('')}</nav></div><div class="sidebar-mission"><div class="eyebrow">ACTIVE SCENARIO</div><h3>Lunar Polar Mapper</h3><p>Moon · Polar science orbit</p><div class="badge" style="margin-top:14px">EDUCATIONAL MODEL</div></div><div class="sidebar-bottom">CREATED BY<strong>Kemon Dilam Bondhura</strong><br>Design → Consequence → Redesign<br>Version ${VERSION}</div></aside>
  <main class="main" id="main-content">${state.pitch?pitchBanner():''}${content}<div class="footer-note"><span>Educational first-order mission model. Simplified values; not flight design certification.</span><span>NASA/JPL data snapshot · Fictional hardware & costs</span></div></main></div>`;
  document.body?.classList.toggle('reduced-motion',state.prefs.reducedMotion);
  document.body?.classList.toggle('game-page',state.page==='game');
  document.body?.classList.toggle('focus-game',state.game.fullscreen&&state.page==='game');
  const newCanvas=$('#game-canvas');
  if(newCanvas){if(oldCanvas&&spaceRenderer){newCanvas.replaceWith(oldCanvas);}else{try{spaceRenderer=mountSpace3D(newCanvas,()=>({stage:state.game.stage==='brief'?'hangar':state.game.stage,design:state.run&&state.game.stage==='flight'?state.run.design:state.design,run:state.game.stage==='flight'?state.run:null,period:calculate(state.run&&state.game.stage==='flight'?state.run.design:state.design).period,selected:state.category,playing:state.playing,reducedMotion:state.prefs.reducedMotion}),k=>{state.category=k;render();toast(`${CATEGORIES.find(c=>c[0]===k)?.[1]||k} selected. Choose a module on the left.`);});if(!spaceRenderer.supported){spaceRenderer=null;showSceneFallback();}}catch{spaceRenderer=null;showSceneFallback();}}}else if(spaceRenderer){spaceRenderer.dispose();spaceRenderer=null;}
}
function pitchBanner(){return `<div class="pitch-banner"><div><strong>90-SECOND PITCH PATH</strong><p>Fragile design → launch → eclipse / backlog → explain why → upgrade power + comms → compare.</p></div><div class="button-group">${button('Fragile preset','preset-fragile','small')}${button('Redesign fix','preset-resilient','small')}${button('Exit','exit-pitch','small ghost')}</div></div>`;}
function landing(){return `<section class="landing"><div class="landing-scene">${scene({running:true,large:true})}</div><div class="hero-content"><div class="eyebrow">YOUR MISSION. EVERY DECISION MATTERS.</div><h1>Space is hard.<br><em>Design smarter.</em></h1><p>Build a spacecraft. Manage the unexpected. Discover how one engineering choice can change an entire mission.</p><div class="hero-buttons">${button('Start your mission <span class="arrow">↗</span>','start','primary')}${button('Try the consequence demo','pitch','ghost')}</div><div class="hero-meta"><div><strong>01</strong>Complete lunar mission</div><div><strong>07</strong>Connected subsystems</div><div><strong>∞</strong>Ways to learn</div></div></div><div class="landing-bottom"><div class="landing-step"><span>01 / DESIGN</span><h3>Make the trade-off.</h3><p>Balance science ambition against power, mass, data and your budget.</p></div><div class="landing-step"><span>02 / EXPERIENCE</span><h3>Face the consequence.</h3><p>Navigate eclipse, maneuver limits and science stranded in storage.</p></div><div class="landing-step"><span>03 / UNDERSTAND</span><h3>Redesign with evidence.</h3><p>See the causal chain. Change your design. Compare the improvement.</p></div></div></section>`;}
function brief(){return `${heading('01 / MISSION BRIEF','The Moon is waiting.','Your objective defines the spacecraft. Start with the science.',button('Build spacecraft ↗','architect','primary'))}<div class="brief-grid"><div class="panel panel-pad"><div class="section-title"><span class="kicker">MISSION LP-01</span><span class="badge">LUNAR SCIENCE</span></div><div class="brief-visual">${scene({running:true})}</div><div class="brief-objective"><h2>${M.title}</h2><p>${M.subtitle} Design a small orbital mapper that returns useful observations of the lunar polar region. Getting there is only the beginning: the science must reach Earth.</p></div></div><div class="stack"><div class="two-col">${stat('BUDGET','150 <small>cr</small>','Fictional cost credits')}${stat('MASS ALLOWANCE','220 <small>kg</small>','Default injected spacecraft')}${stat('SCIENCE TARGET','650 <small>units</small>','Quality-weighted returned data')}${stat('CAMPAIGN','240 <small>min</small>','After lunar capture')}</div><div class="panel panel-pad"><h3>What success looks like</h3><div class="objectives"><div class="objective"><span class="circle">1</span><div>Reach lunar mapping orbit<p>650 m/s spacecraft maneuver + 100 m/s reserve.</p></div></div><div class="objective"><span class="circle">2</span><div>Return at least 80% of the science target<p>Only downlinked science counts. Data in storage does not.</p></div></div><div class="objective"><span class="circle">3</span><div>Keep the spacecraft functioning<p>Survive eclipse, schedule contacts and protect the energy reserve.</p></div></div></div><div class="notice">Scenario requirements are teaching assumptions. Launch is compressed; Earth escape is supplied by the chosen provider. This is not a full Earth-to-Moon trajectory solver.</div></div></div></div>${insight('A bigger instrument is only useful if the spacecraft can power it, point it and return its data.')}`;}
function stat(label,value,description='',cls=''){return `<div class="stat ${cls}"><div class="label">${label}</div><div class="value">${value}</div><div class="description">${description}</div></div>`;}
function insight(s){return `<div class="insight"><strong>TRAJECTIQ INSIGHT</strong><p>${s}</p></div>`;}
function architect(){const a=calculate(state.design),cat=state.category;return `${heading('02 / MISSION ARCHITECT','Build with intention.','Every subsystem changes the mission. Watch the margins move.',button('Readiness review ↗','readiness','primary'))}<div class="architect-grid"><div class="panel panel-pad"><div class="architecture-top"><span class="kicker" style="margin-right:auto;align-self:center">YOUR SPACECRAFT / LP-01</span>${button('Balanced','preset-balanced','small ghost')}${button('Fragile','preset-fragile','small ghost')}${button('Resilient','preset-resilient','small ghost')}</div><div class="category-tabs" role="group" aria-label="Subsystems">${CATEGORIES.map(([id,t])=>`<button class="category-tab ${id===cat?'selected':''}" data-category="${id}" aria-pressed="${id===cat}">${t}</button>`).join('')}</div><div class="section-title"><h3>${CATEGORIES.find(x=>x[0]===cat)[2]}</h3><span class="kicker">SELECT ONE CLASS</span></div><div class="component-grid">${CATALOG[cat].map(c=>componentCard(c,cat,a)).join('')}</div><div class="slider-grid">${range('fuel','Propellant load',state.design.fuel,0,a.c.propulsion.maxFuel,'kg','More fuel increases Δv and wet mass.')}${range('altitude','Orbit altitude',state.design.altitude,50,200,'km','Higher altitude lengthens the orbit but reduces mapping detail.')}<div class="slider-field"><label for="inclination">Orbit inclination <strong>${state.design.inclination}°</strong></label><select id="inclination" data-field="inclination"><option value="90" ${state.design.inclination===90?'selected':''}>90° · Polar orbit</option><option value="60" ${state.design.inclination===60?'selected':''}>60° · Mid-inclination</option><option value="30" ${state.design.inclination===30?'selected':''}>30° · Low-inclination</option></select><small>Polar mapping needs polar coverage.</small></div><div class="slider-field"><label>Orbit period <strong>${fmt(a.period,1)} min</strong></label><small>Derived from JPL Moon radius and GM using the circular two-body period equation.</small></div></div><div class="loadout">${CATEGORIES.map(([k,t])=>`<span>${t}: <b>${a.c[k].name}</b></span>`).join('')}</div></div>${marginRail(a)}</div>${insight(cat==='comms'?'Storage can postpone a loss. Communications turns stored observations into completed science.':cat==='power'?'A positive solar margin does not guarantee eclipse survival. Check battery energy as well as watts.':cat==='propulsion'?'Propellant buys maneuver capability but uses the same launch mass allowance as your instrument.':'Design is a system of linked decisions. Optimize the mission, not one component.')}`;}
function componentCard(c,cat,a){const selected=state.design[cat]===c.id;let extra=cat==='power'?`${c.solar} W · ${c.battery} Wh`:cat==='payload'?`${c.dataMbps} Mb/s`:cat==='comms'?`${c.downlinkMbps} Mb/s`:cat==='propulsion'?`${c.isp} s Isp`:cat==='storage'?`${c.capacity} MB`:cat==='bus'?`${c.pointing}″ pointing`:`${c.capacity} kg capacity`;return `<button class="component ${selected?'selected':''}" data-component="${c.id}" data-kind="${cat}" aria-pressed="${selected}" title="${esc(c.source_note)}"><span class="eyebrow">${c.label}</span><span class="selected-mark">${selected?'✓':''}</span><h3>${c.name}</h3><p>${c.note}</p><div class="component-stats"><span>MASS<strong>${c.mass} kg</strong></span><span>COST<strong>${c.cost} cr</strong></span><span>${cat==='power'?'ENERGY':'CAPABILITY'}<strong>${extra}</strong></span></div><span class="assumption-tag">Educational component class · assumptions</span></button>`;}
function range(id,label,v,min,max,unit,note){return `<div class="slider-field"><label for="${id}">${label}<strong>${v} ${unit}</strong></label><input id="${id}" data-field="${id}" type="range" min="${min}" max="${max}" value="${v}" step="${id==='altitude'?10:1}" aria-label="${label}"><small>${note}</small></div>`;}
function marginRail(a){const vals=[['MASS MARGIN',`${fmt(a.margins.mass,1)} kg`,a.margins.mass,a.c.launch.capacity,`${fmt(a.wet,1)} kg wet / ${a.c.launch.capacity} kg capacity`,'Sum of selected hardware + 15 kg structure + fuel. Educational masses.'],['PEAK POWER',`${fmt(a.margins.power)} W`,a.margins.power,a.c.power.solar,`85% solar − ${a.peak} W simultaneous peak`,'W = power. Wh = energy. Peak margin is conservative; normal modes separate science and downlink.'],['MANEUVER RESERVE',`${fmt(a.margins.deltaV)} m/s`,a.margins.deltaV,750,`${fmt(a.deltaV)} available / 750 required`,'Derived rocket equation with assumed Isp and fuel. Required 650 + 100 reserve is an assumption.'],['CONTACT MARGIN',`${fmt(a.margins.data)} MB`,a.margins.data,Math.max(a.dataGenerated,a.dataDownlink),`${fmt(a.dataGenerated)} MB generated / ${fmt(a.dataDownlink)} returned per orbit`,'Ideal per-orbit data budget, scheduled sunlit science and 25 min contact. Mb/s divided by 8 gives MB/s.'],['BUDGET REMAINING',`${fmt(a.margins.budget)} cr`,a.margins.budget,M.budget,`${a.cost} used / 150 credits`,'Fictional educational costs, not commercial launch prices.'],['ECLIPSE RESERVE',`${fmt(a.margins.eclipse,1)} Wh`,a.margins.eclipse,a.c.power.battery,`${fmt(a.eclipseEnergy,1)} Wh uninterrupted science demand`,'85% usable battery minus 35-minute full-science eclipse energy. Science is normally paused in eclipse.']];return `<aside class="panel margin-rail"><div class="section-title"><h3>Live engineering margins</h3><span class="badge">${a.risk} WARN</span></div>${vals.map(([label,value,margin,max,desc,tip])=>`<div class="margin-item" title="${esc(tip)}"><div class="row"><span>${label}</span><strong class="${margin<0?'warning':'good'}">${value}</strong></div><div class="bar"><i class="${margin<0?'warn':''}" style="width:${clamp(Math.abs(margin)/Math.max(1,max)*100,4,100)}%"></i></div><small>${desc}</small></div>`).join('')}<div class="rail-bottom">${button(a.launchable?'Review before launch ↗':'Resolve blocked checks','readiness','primary')}<small style="display:block;margin-top:10px;color:var(--dim);font-size:9px">${a.launchable?'Advisory warnings may be accepted.':'Mass, budget and compatibility failures block launch.'}</small></div></aside>`;}
function readiness(){const a=calculate(state.design),r=state.robust;return `${heading('03 / READINESS REVIEW','Know what you are accepting.','A warning is a trade-off. A hard failure needs a redesign.',button('← Adjust design','architect','ghost'))}<div class="readiness-grid"><div class="panel panel-pad"><div class="section-title"><h3>Launch authorization checks</h3><span class="badge ${a.launchable?'good':'bad'}">${a.launchable?'NO HARD FAILURES':'LAUNCH BLOCKED'}</span></div><div class="check-list">${a.checks.map(c=>`<div class="check-row"><span class="status ${c.status}">${c.status.toUpperCase()}</span><div><h3>${c.name}</h3><p>${c.why}</p></div><div class="check-value">${c.value}</div></div>`).join('')}</div></div><div class="stack"><div class="panel panel-pad"><div class="eyebrow">YOUR CALL, COMMANDER</div><h2 style="margin:15px 0">${a.launchable?'Ready, with trade-offs.':'Redesign required.'}</h2><p style="font-size:12px;margin-bottom:20px">${a.launchable?`${a.risk} advisory warning${a.risk===1?'':'s'} remain. The mission will simulate their consequences; a green launch gate does not guarantee the science objective.`:'The selected architecture violates a hard launch constraint. Change the exact subsystem flagged in the checks.'}</p>${button('Authorize launch ↗','launch','primary',!a.launchable?'disabled':'')}<p style="font-size:10px;margin-top:14px">${state.pitch?'Pitch mode uses aggressive collection to expose weak battery reserves.':'Default operations pause science in eclipse and use contact windows for downlink.'}</p></div><div class="panel panel-pad"><div class="section-title"><h3>Educational Robustness Index</h3><span class="kicker">200 SAMPLES</span></div>${r?`<div class="robust-value ${r.index>=80?'good':'warning'}">${fmt(r.index)}<small>%</small></div><p style="font-size:11px">${r.passed} / ${r.samples} modeled variations met the mission objective using a fixed conservative recovery policy.</p>${histogram(r.results||[])}<small class="dim">Mean science completion ${fmt(r.meanCompletion,1)}% · seed ${r.seed}</small>`:'<p style="font-size:11px;margin:15px 0">Test the same design under modest performance degradation. This is a model sensitivity check, not real-world reliability.</p>'}<div style="margin-top:17px">${button(r?'Recompute sample set':'Sample uncertainty','robust','small ghost',!a.launchable?'disabled':'')}</div><div class="uncertainty-list" style="margin-top:15px">Solar output × 0.80–1.00<br>Link availability × 0.65–1.00<br>Specific impulse × 0.95–1.00<br>Pointing error × 1.00–1.25<br>Independent uniform factors · seed 4385</div></div></div></div>${insight('Launch authorization checks feasibility. Success still depends on how the spacecraft behaves over time.')}`;}
function histogram(results){const counts=Array(10).fill(0);results.forEach(v=>counts[Math.min(9,Math.floor(v/10))]++);const max=Math.max(1,...counts);return `<div class="histogram" role="img" aria-label="Histogram of modeled science completion from zero to one hundred percent">${counts.map((n,i)=>`<i title="${i*10}–${(i+1)*10}%: ${n} samples" style="height:${Math.max(3,n/max*100)}%"></i>`).join('')}</div>`;}
function control(){const s=state.run;if(!s)return empty('No mission in flight.','Review your design and authorize launch to open mission control.','readiness','Review readiness');const a=calculate(s.design),pct=s.battery/a.c.power.battery*100;return `${heading('04 / MISSION CONTROL','Your design is now in flight.','Manage the consequences. The engine determines the outcome.',`${button('Explain this state','mentor','ghost small')}${button('Export telemetry','export','ghost small')}`)}<div class="phase-strip">${['launch','transfer','capture','operations','debrief'].map(p=>`<div class="phase-chip ${s.phase===p?'active':''}">${p.toUpperCase()}</div>`).join('')}</div><div class="control-grid"><div><div class="panel control-visual"><div class="scene-top"><span class="phase"><i class="online-dot"></i>${s.phase.toUpperCase()} / LP-01</span><span class="badge ${s.safe?'warning':''}">${s.safe?'SAFE MODE':s.eclipse?'ECLIPSE':s.contact?'GROUND CONTACT':'SUNLIT'}</span></div><div class="control-scene">${scene({running:state.playing&&!s.crisis,eclipse:s.eclipse,contact:s.contact,phase:s.phase})}</div><div class="scene-caption">${s.design.altitude} KM · ${s.design.inclination}° · ${fmt(a.period,1)} MIN PERIOD</div><div class="scene-legend"><span><i></i>TRAJECTORY SCHEMATIC</span><span><i style="background:var(--lime)"></i>LP-01 MAPPER</span></div></div><div class="telemetry">${stat('BATTERY',`${fmt(pct)}<small>%</small>`,`${fmt(s.battery,1)} / ${a.c.power.battery} Wh`,pct<30?'warning':'')}${stat('RECORDER',`${fmt(s.backlog)} <small>MB</small>`,`${fmt(s.backlog/a.c.storage.capacity*100)}% of ${a.c.storage.capacity} MB`)}${stat('SCIENCE RETURN',`${fmt(clamp(s.science/M.scienceTarget*100,0,100))}<small>%</small>`,`${fmt(s.science)} / 650 target units`)}${stat('PROPELLANT',`${fmt(s.fuel,1)} <small>kg</small>`,'Remaining after maneuvers')}</div><div class="control-buttons"><div class="button-group">${button(state.playing?'Ⅱ Pause':'▶ Resume','play','primary',s.done||s.crisis?'disabled':'')}${button('Step +5 min','step','ghost',s.done||s.crisis?'disabled':'')}${button('Fast-forward','fast','ghost',s.done||s.crisis?'disabled':'')}</div><div class="button-group">${[1,3,10].map(n=>button(`${n}×`,`speed-${n}`,`small ${state.speed===n?'':'ghost'}`)).join('')}</div></div>${s.crisis?crisisCard(s.crisis):''}<div class="panel panel-pad" style="margin-top:18px"><div class="section-title"><h3>Battery / mission history</h3><span class="kicker">% STATE OF CHARGE</span></div>${sparkline(s.history)}<div class="progress-top"><span>0 min</span><span>${s.minute} / 240 minutes</span></div><div class="bar"><i style="width:${s.minute/M.duration*100}%"></i></div></div></div><div class="stack"><div class="panel panel-pad"><div class="eyebrow">MISSION CLOCK</div><div class="robust-value" style="font-size:37px;margin:12px 0">T+${fmt(s.minute,1)}<small> min</small></div><p style="font-size:11px">${s.phase==='operations'?'Four-hour mapping campaign. Contact and shadow windows repeat each orbit.':'Launch and transfer are compressed stages; they do not consume campaign time.'}</p><div class="mode-row"><label class="kicker" for="mode">Operations schedule</label><select id="mode" data-field="mode" ${s.crisis?'disabled':''}><option value="science" ${s.mode==='science'?'selected':''}>Adaptive · sunlit science</option><option value="aggressive" ${s.mode==='aggressive'?'selected':''}>Aggressive · science in eclipse</option><option value="downlink" ${s.mode==='downlink'?'selected':''}>Return priority · pause science</option></select><small>Science and transmission are normally scheduled separately. Aggressive mode also collects in eclipse.</small></div></div><div class="panel panel-pad"><div class="section-title"><h3>Mission event log</h3><span class="kicker">${s.logs.length} ENTRIES</span></div><div class="event-log">${s.logs.slice().reverse().map(l=>`<div class="log-row"><span class="log-time">T+${fmt(l.minute,1)}</span><div><strong class="${l.type==='warning'?'warning':l.type==='success'?'good':l.type==='decision'?'cyan':''}">${l.title}</strong><p>${l.detail}</p></div></div>`).join('')}</div></div></div></div>${insight(s.crisis?'This event follows from your architecture and operating choices. Choose a recovery action to continue.':s.backlog>100?'Science onboard is potential. Science downlinked is progress. Keep watching contact capacity.':'Your energy, science and data budgets are updating every five simulated minutes.')}`;}
function crisisCard(e){return `<section class="panel crisis-card" role="region" aria-label="Mission recovery decision"><div class="eyebrow warning">DECISION REQUIRED · SIMULATION PAUSED</div><h2>${e.title}</h2><p>${e.body}</p>${chain(e.chain)}<button class="btn ghost small" data-ask="Compare crisis choices">Preview consequences with copilot</button><div class="crisis-actions">${e.actions.map(a=>`<button class="crisis-action" data-recovery="${a.id}" ${a.disabled?'disabled':''}><strong>${a.name}</strong><small>${a.effect}${a.disabled?' Unavailable: insufficient capability.':''}</small></button>`).join('')}</div></section>`;}
function chain(items){return `<div class="chain">${items.map((s,i)=>`${i?'<span class="chain-arrow" aria-hidden="true">→</span>':''}<span class="chain-node">${s}</span>`).join('')}</div>`;}
function sparkline(history){if(!history.length)return `<svg class="sparkline" viewBox="0 0 600 90" role="img" aria-label="Battery history will appear as the mission advances"><text x="300" y="48" text-anchor="middle" fill="#718393" font-family="monospace" font-size="10">Telemetry begins during operations</text></svg>`;const points=history.map(h=>`${h.minute/240*590+5},${85-h.battery*.75}`).join(' ');return `<svg class="sparkline" viewBox="0 0 600 90" role="img" aria-label="Battery state of charge over the mission"><path d="M0 10H600M0 48H600M0 85H600" stroke="#253444" stroke-width=".5"/><line x1="0" y1="73.75" x2="600" y2="73.75" stroke="#ffbc6e" stroke-dasharray="4 5" opacity=".5"/><polyline fill="none" stroke="#ccff6b" stroke-width="2" points="${points}"/><text x="580" y="69" fill="#ad8f67" font-size="8" font-family="monospace">15%</text></svg>`;}
function debriefPage(){const s=state.run?.done?state.run:state.runs.at(-1);if(!s)return empty('Every outcome has a reason.','Complete a mission to see its causal debrief and redesign recommendations.','architect','Design your mission');const o=s.outcome,d=debrief(s),previous=state.runs.filter(r=>r.id!==s.id).at(-1);return `${heading('05 / CAUSAL DEBRIEF','Understand. Then improve.','Your mission result is evidence for the next design.',`${button('Export report ↓','export','ghost small')}${button('Redesign this mission ↗','redesign','primary')}`)}<div class="panel debrief-hero"><div class="completion-ring" style="--p:${o.completion}"><div class="ring-inner"><strong>${fmt(o.completion)}%</strong><span>SCIENCE TARGET</span></div></div><div><div class="eyebrow ${o.achieved?'good':'warning'}">${o.achieved?'MISSION OBJECTIVE ACHIEVED':'MISSION OBJECTIVE INCOMPLETE'}</div><h2 style="margin-top:12px">${o.achieved?'The science made it home.':'The trade-offs caught up.'}</h2><p>${fmt(o.science)} science units returned. ${fmt(o.retainedMB,1)} MB remain onboard, and ${fmt(o.lostMB,1)} MB were discarded. Your objective required at least 520 returned science units.</p></div>${button('Explore trade space ↗','trade','ghost')}</div><div class="three-col debrief-stats">${stat('SCIENCE RETURN',`${fmt(o.returned,1)} <small>MB</small>`,'Useful science is quality weighted')}${stat('FINAL BATTERY',`${fmt(o.finalBattery)}<small>%</small>`,`${fmt(o.safeMinutes,1)} minutes in safe mode`)}${stat('MISSION COST',`${o.cost} <small>cr</small>`,`${fmt(o.efficiency,1)} science units / credit`)}</div><div class="two-col"><div class="stack"><div class="section-title" style="margin:4px 0 0"><h3>Decision → consequence</h3><span class="kicker">${d.items.length} CAUSAL TRACES</span></div>${d.items.length?d.items.map(e=>`<div class="panel cause-card"><h3>${e.title}</h3>${chain(e.chain)}<p>${e.impact}</p><div class="recovery">YOUR RESPONSE / ${e.action}</div></div>`).join(''):`<div class="panel cause-card"><h3>Margins supported the campaign</h3>${chain(['Compatible architecture','Energy and contact capacity supported demand','Observations returned before campaign ended'])}<p>No crisis threshold was crossed. Try a lower-cost design to discover where the reserves matter.</p></div>`}</div><div class="stack"><div class="panel panel-pad"><div class="section-title"><h3>Redesign recommendations</h3><span class="badge">RULE-BASED</span></div>${d.tips.map(t=>`<div class="tip"><span>↗</span>${t}</div>`).join('')}${button('Apply power + comms fix','preset-resilient','primary small')}<p style="font-size:10px;margin-top:13px">The fix preserves the high-science payload and upgrades the two supporting subsystems. Recheck mass and budget.</p></div><div class="panel panel-pad"><h3>Compare the previous run</h3>${previous?comparison(previous,s):'<p style="font-size:12px;margin-top:13px">Finish a second design to compare the result. Saved runs remain in this browser.</p>'}</div><div class="panel panel-pad"><h3>What did you learn?</h3><p style="font-size:11px;margin:12px 0">Check whether you can explain why stored data does not complete a science objective.</p>${button('Take the 3-question check','quiz','ghost small')}</div></div></div>${insight('A failure becomes useful when you can identify the decision that caused it and test a better alternative.')}`;}
function comparison(before,after){const changed=CATEGORIES.filter(([k])=>before.design[k]!==after.design[k]).map(([,t])=>t);if(before.design.fuel!==after.design.fuel)changed.push('Propellant');if(before.design.altitude!==after.design.altitude||before.design.inclination!==after.design.inclination)changed.push('Orbit');for(const [k,label] of [['arrayScale','Solar array size'],['batteryScale','Battery size'],['duty','Instrument duty'],['distance','Distance scenario']])if(before.design[k]!==after.design[k])changed.push(label);return `<p style="font-size:10px;margin:13px 0">${before.modelVersion!==after.modelVersion?'Different model versions; do not attribute all changes to hardware alone. ':''}Changed: ${changed.join(', ')||'same architecture; compare operating decisions'}.</p><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Metric</th><th>Before</th><th>Now</th><th>Change</th></tr></thead><tbody>${[['Science %','completion',1],['Cost · cr','cost',0],['Returned · MB','returned',1],['Lost · MB','lostMB',1],['Safe mode · min','safeMinutes',0]].map(([label,key,n])=>{const v=after.outcome[key]-before.outcome[key];return `<tr><td>${label}</td><td>${fmt(before.outcome[key],n)}</td><td>${fmt(after.outcome[key],n)}</td><td class="${(key==='lostMB'||key==='safeMinutes'||key==='cost'?v<0:v>0)?'good':''}">${v>0?'+':''}${fmt(v,n)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function trade(){const runs=state.runs,frontier=pareto(runs);return `${heading('06 / TRADE SPACE','There is no perfect spacecraft.','Compare what each architecture bought—and what it gave up.',`${button('New architecture ↗','architect','primary')}${button('Clear run history','clear-history','ghost small')}`)}<div class="two-col"><div class="panel panel-pad"><div class="section-title"><h3>Science completion vs mission cost</h3><span class="kicker">${runs.length} SAVED RUNS</span></div>${tradePlot(runs,frontier)}<div class="legend"><span><i class="key lime"></i>Non-dominated design</span><span><i class="key"></i>Other designs</span></div><p style="font-size:10px;margin-top:13px">A design is non-dominated when no saved run returns at least as much science for an equal or lower cost, with one strict improvement. Bubble size represents time in safe mode, not real-world risk.</p></div><div class="panel panel-pad"><h3>What makes a useful trade study?</h3><div class="objectives"><div class="objective"><span class="circle">1</span><div>Keep the objective fixed<p>All runs use the same 650-unit target and four-hour campaign.</p></div></div><div class="objective"><span class="circle">2</span><div>Change a small number of choices<p>Isolate the effect of power, communications or the instrument.</p></div></div><div class="objective"><span class="circle">3</span><div>Compare the engineering evidence<p>Look at returned science, cost, lost data and safe-mode time.</p></div></div></div>${runs.length>=2?comparison(runs.at(-2),runs.at(-1)):'<p style="font-size:11px">Complete two missions to show before-and-after metrics here.</p>'}</div></div><div class="panel panel-pad" style="margin-top:20px"><h3>Mission archive</h3><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Run</th><th>Payload</th><th>Power / comms</th><th>Cost</th><th>Science</th><th>Outcome</th><th></th></tr></thead><tbody>${runs.length?runs.slice().reverse().map(r=>{const c=calculate(r.design).c;return `<tr><td class="mono">${r.label}</td><td>${c.payload.name}</td><td>${c.power.name}<br>${c.comms.name}</td><td>${r.outcome.cost} cr</td><td>${fmt(r.outcome.completion,1)}%</td><td class="${r.outcome.achieved?'good':'warning'}">${r.outcome.achieved?'Achieved':'Incomplete'}</td><td><button class="btn small ghost" data-loadrun="${r.id}">Review</button></td></tr>`;}).join(''):'<tr><td colspan="7" class="muted">Your completed missions will appear here.</td></tr>'}</tbody></table></div></div>${insight('The best architecture depends on the objective and constraints. Explore alternatives before choosing a winner.')}`;}
function tradePlot(runs,frontier){const x=v=>58+(v/170)*480,y=v=>250-v*2;const grid=[0,20,40,60,80,100].map(v=>`<line x1="58" y1="${y(v)}" x2="548" y2="${y(v)}" stroke="#293747" stroke-dasharray="3 6"/><text x="42" y="${y(v)+3}" fill="#8293a5" font-family="monospace" font-size="9" text-anchor="end">${v}%</text>`).join('');return `<svg class="trade-plot" viewBox="0 0 600 300" role="img" aria-label="Saved mission cost and science completion scatter plot">${grid}<line x1="58" y1="250" x2="548" y2="250" stroke="#3d4e5f"/>${[0,50,100,150].map(v=>`<text x="${x(v)}" y="270" fill="#8293a5" font-family="monospace" font-size="9" text-anchor="middle">${v}</text>`).join('')}<text x="300" y="294" text-anchor="middle" fill="#8293a5" font-family="monospace" font-size="9">MISSION COST / CREDITS</text>${runs.map((r,i)=>`<g><circle cx="${x(r.outcome.cost)}" cy="${y(r.outcome.completion)}" r="${7+Math.min(12,r.outcome.safeMinutes/5)}" fill="${frontier[i]?'#ccff6b':'#7cdbf3'}" fill-opacity=".55" stroke="${frontier[i]?'#ccff6b':'#7cdbf3'}"><title>${r.label}: ${fmt(r.outcome.completion,1)}% science, ${r.outcome.cost} credits, ${r.outcome.safeMinutes} min safe mode</title></circle><text x="${x(r.outcome.cost)+10}" y="${y(r.outcome.completion)-10}" fill="#c3ced9" font-family="monospace" font-size="9">${r.label}</text></g>`).join('')}${runs.length?'':'<text x="300" y="145" text-anchor="middle" fill="#718393" font-size="12">Complete a mission to add a design.</text>'}</svg>`;}
function sources(){return `${nasaPanel()}${heading('07 / SOURCES & METHOD','Show your working.','Transparent equations. Explicit assumptions. Traceable references.')}<div class="notice" style="margin-bottom:20px">This is a preparation prototype based on the supplied v1 playbook. Audit it against the final challenge brief and event rules before submission. NASA references inform the model; NASA has not approved this game. NASA/JPL numeric snapshot is bundled offline. No live ephemeris, measured hardware specification or LRO terrain raster is loaded.</div><div class="two-col"><div class="stack"><div class="panel method-card"><div class="eyebrow">DERIVED / PHYSICS</div><h3 style="margin-top:12px">Mass & propulsion</h3><div class="formula">m₀ = Σ hardware + structure + propellant<br>Δv = Isp × 9.80665 × ln(m₀ / mf)</div><p>Mass in kg, specific impulse in seconds, Δv in m/s. Structure allowance is 15 kg. Maneuver propellant is consumed using the inverse rocket equation. No thrust-duration or multi-body trajectory calculation is performed.</p></div><div class="panel method-card"><div class="eyebrow">DERIVED / ORBIT</div><h3 style="margin-top:12px">Circular orbit period</h3><div class="formula">T = 2π √((R + h)³ / μ)</div><p>R = 1,737.4 km and μ = 4,902.800 km³/s² from JPL. Divide T by 60 for minutes. Inclination/altitude quality penalties, 35-minute eclipse and 25-minute contact windows are assumptions—not computed ground geometry.</p></div><div class="panel method-card"><div class="eyebrow">DERIVED / ENERGY</div><h3 style="margin-top:12px">Battery integration</h3><div class="formula">E(next) = clamp(E + (Pgen − Pload) × Δt / 60)</div><p>E in Wh, power in W, Δt ≤ 1 minute, split at orbit window boundaries. Generation is zero in eclipse and 85% array rating otherwise. Safe mode begins at ≤15% state of charge and ends above 40%. Loads change with science, downlink and recovery modes.</p></div><div class="panel method-card"><div class="eyebrow">DERIVED / INFORMATION</div><h3 style="margin-top:12px">Data → returned science</h3><div class="formula">MB = Mb/s × seconds / 8<br>Science = quality × duty × time × 10</div><p>Only accepted data is stored. Overflow discards new data. Quality-weighted science is downlinked proportionally to bytes drained from the buffer. Science depends on payload quality, pointing, inclination and altitude. Unreturned observations do not count.</p></div></div><div class="stack"><div class="panel"><div class="panel-pad" style="padding-bottom:0"><h3>NASA & JPL reference map</h3></div>${SOURCES.map(s=>`<div class="source-card"><span class="badge">${s.type}</span><br><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><p>${s.use}</p></div>`).join('')}</div><div class="panel method-card"><h3>Uncertainty is not mission probability</h3><p>200 fixed-seed samples vary independent uniform solar [0.80, 1.00], link [0.65, 1.00], Isp [0.95, 1.00] and pointing-error [1.00, 1.25] multipliers. A fixed conservative policy handles every event. The index is the fraction achieving ≥80% target science and ending with battery above zero in this model.</p><p>It is an educational robustness indicator, not a real-world chance of success. It does not estimate hardware failure probability, mission certification or spacecraft safety.</p></div><div class="panel method-card"><h3>Assumption register</h3><p>${M.assumption}</p><p>All costs are fictional credits. Payload science scores, 85% operating derating (not cell efficiency), safe-mode thresholds, a 45% degraded-link contact and the alternate-capture penalty are game assumptions. Components are fictional classes.</p><p>Limitations: no thermal solver, radiation model, detailed RF budget, n-body propagation, real ground stations or validated learning-impact study. The mission mentor is a deterministic explanation tool; no paid AI service is used.</p></div></div></div><div class="panel panel-pad" style="margin-top:20px"><h3>Versioned component catalog / educational values</h3><div class="table-scroll"><table class="catalog-table"><thead><tr><th>Class</th><th>Mass · kg</th><th>Load · W</th><th>Cost · cr</th><th>Evidence classification</th></tr></thead><tbody>${Object.values(CATALOG).flat().map(c=>`<tr><td>${c.name}</td><td>${c.mass}</td><td>${c.power}</td><td>${c.cost}</td><td>Educational assumption</td></tr>`).join('')}</tbody></table></div></div>`;}
function empty(title,description,action,label){return `<div class="panel empty"><div class="eyebrow">TRAJECTIQ</div><h2>${title}</h2><p>${description}</p>${button(label,action,'primary')}</div>`;}
function go(page){if(state.playing&&page!=='control'&&page!=='game')pause();state.page=page;render();window.scrollTo({top:0,behavior:'instant'});}
function pause(){state.playing=false;if(timer){clearInterval(timer);timer=null;}}
function clockDelay(){return state.page==='game'&&state.run?.phase!=='operations'?1900:Math.max(100,1400/state.speed);}
function play(){if(!state.run||state.run.done||state.run.crisis||$('#modal-root').firstChild)return;state.playing=true;clearInterval(timer);timer=setInterval(()=>{tick();},clockDelay());render();}
function tick(){if(!state.run||state.run.done||state.run.crisis)return;const oldPhase=state.run.phase;state.run=advance(state.run);if(state.run.crisis){pause();render();setTimeout(()=>$('.crisis-card')?.scrollIntoView({behavior:'smooth',block:'center'}),50);}else if(state.run.done){finishUI();}else{if(oldPhase!==state.run.phase&&state.playing){clearInterval(timer);timer=setInterval(()=>tick(),clockDelay());}render();}}
function finishUI(){const inGame=state.page==='game';pause();const r=state.run;if(!r.id){r.id=crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${state.runs.length}`;r.label=`R${String(state.runs.length+1).padStart(2,'0')}`;r.modelVersion=VERSION;r.completedAt=new Date().toISOString();state.runs.push(clone(r));state.runs=state.runs.slice(-20);persist();}if(inGame){state.game.stage='report';go('game');}else go('debrief');}
function preset(name){const inGame=state.page==='game';pause();state.design=normalize(PRESETS[name]);state.robust=null;state.category='payload';state.game.stage='hangar';persist();go(inGame?'game':'architect');toast(`${name[0].toUpperCase()+name.slice(1)} architecture loaded.`);}
function launch(){const inGame=state.page==='game';pause();try{state.run=newRun(state.design);state.run.mode=state.pitch?'aggressive':'science';if(inGame)state.game.stage='flight';go(inGame?'game':'control');play();}catch(e){toast(e.message);}}
function fast(){pause();if(!state.run)return;for(let i=0;i<150&&!state.run.done&&!state.run.crisis;i++)state.run=advance(state.run);if(state.run.done)finishUI();else{render();setTimeout(()=>$('.crisis-card')?.scrollIntoView({behavior:'smooth',block:'center'}),50);}}
function exportReport(){const r=state.run||state.runs.at(-1);const doc={nasaSnapshot:NASA_DATA,project:'TRAJECTIQ',team:'Kemon Dilam Bondhura',version:VERSION,mission:M,design:r?.design||state.design,run:r,debrief:r?.done?debrief(r):null,robustness:state.robust,classification:'Educational first-order model; no real-world mission probability',sources:SOURCES};const blob=new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='TRAJECTIQ_mission_report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(body){if(state.playing){pause();render();}lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Mission learning tool">${body}</section></div>`;$('#modal-root button')?.focus();}
function closeModal(){$('#modal-root').innerHTML='';if(lastFocus?.isConnected!==false)lastFocus?.focus();else $('#app button')?.focus();}
function activeContext(){return {design:state.design,run:((state.page==='game'&&(state.game.stage==='flight'||state.game.stage==='report'))||['control','debrief'].includes(state.page))?state.run:null,language:state.prefs.language,history:state.chat};}
function mentor(){
 const bn=state.prefs.language==='bn';
 modal(`<div class="modal-top"><div><div class="eyebrow">MISSION COPILOT · FREE & OFFLINE</div><h2>${bn?'আপনার Mission সহকারী':'Your mission assistant'}</h2></div>${button('Close','close','ghost small')}</div><p>${bn?'খেলার নিয়ম, আপনার design, NASA data বা সমস্যা নিয়ে প্রশ্ন করুন।':'Ask about playing, your spacecraft, NASA data or a mission problem.'} <strong>Flight pauses while you read.</strong></p><label for="help-language">Answer language</label><select id="help-language" data-pref="language"><option value="en" ${!bn?'selected':''}>English</option><option value="bn" ${bn?'selected':''}>বাংলা</option></select><div class="assistant-quick">${['Mission status','Review my design','Compare presets','Compare crisis choices','How do I play?'].map(q=>`<button class="btn small ghost" data-ask="${esc(q)}">${q}</button>`).join('')}</div>${assistantContextPanel()}${experimentPanel()}<div id="assistant-thread" class="assistant-thread" role="log" aria-live="polite">${state.chat.map((m,i)=>`<div class="chat-question">${esc(m.q)}</div>${answerCard(m.answer,i)}`).join('')||'<p>I can simulate a change, compare decisions and explain your mission. Try “What if fuel = 45” or “Review my design”. Local reasoning + game engine; no generative AI or API key. I say when I cannot answer.</p>'}</div><form id="assistant-form"><label for="assistant-question">${bn?'আপনার প্রশ্ন':'Your question'}</label><div class="assistant-input"><input id="assistant-question" name="question" maxlength="500" autocomplete="off" placeholder="e.g. How can I avoid losing data?" required><button class="btn primary" type="submit">${bn?'জিজ্ঞেস করুন':'Ask'}</button></div></form>${button(bn?'কথোপকথন মুছুন':'Clear conversation','clear-chat','ghost small')}<details class="help-library"><summary>Browse everything I can explain</summary><div class="assistant-quick">${HELP_TOPICS.map(t=>`<button class="btn small ghost" data-ask="${esc(t[1])}">${esc(t[1])}</button>`).join('')}</div></details>`);
 const thread=$('#assistant-thread');if(thread)thread.scrollTop=thread.scrollHeight;
}
function assistantContextPanel(){
 const ctx=activeContext(),a=calculate(ctx.run?.design||ctx.design),r=ctx.run;
 return `<div class="copilot-context"><span class="badge">${r?r.done?'COMPLETED MISSION':'PAUSED MISSION':'CURRENT DRAFT'}</span><strong>${esc(a.d.name)}</strong><span>${r?`T+${fmt(r.minute,1)} min · ${fmt(r.science)} science returned`:`${fmt(a.cost,1)} / 150 credits · ${fmt(a.wet,1)} kg`}</span><small>Answers use this context. Older answers are snapshots from when you asked.</small></div>`;
}
function experimentPanel(){return `<details class="experiment-panel"><summary>Try a change · no typing needed</summary><p>Preview first. Nothing changes until you click Apply to draft.</p><label for="experiment-part">Component or distance</label><select id="experiment-part"><option value="">Choose an experiment…</option>${CATEGORIES.map(([k,title])=>`<optgroup label="${esc(title)}">${CATALOG[k].map(p=>`<option value="What if ${esc(p.name)}">${esc(p.name)}</option>`).join('')}</optgroup>`).join('')}<optgroup label="Earth–Moon distance"><option value="What if distance near">Near · 363,300 km</option><option value="What if distance mean">Reference · 384,400 km</option><option value="What if distance far">Far · 405,500 km</option></optgroup></select><form id="experiment-form"><div class="experiment-fields"><label>Setting<select id="experiment-field">${EXPERIMENT_FIELDS.map(([k,t])=>`<option value="${k}">${esc(t)}</option>`).join('')}</select></label><label>New value<input id="experiment-value" type="number" step="any" value="45" required></label><button class="btn primary" type="submit">Preview change</button></div></form><small id="experiment-range">Fuel: 0–${calculate(activeContext().run?.design||state.design).c.propulsion.maxFuel} kg. Duty uses 0.25–1; size uses 0.75–1.5.</small></details>`;}
function comparisonTable(rows){return `<div class="table-scroll copilot-comparison" tabindex="0" aria-label="Simulated design comparison"><table><caption>Game simulation results · science threshold 520</caption><thead><tr><th scope="col">Scenario</th><th scope="col">Returned science</th><th scope="col">Final battery</th><th scope="col">Discarded data</th><th scope="col">Cost</th><th scope="col">Mass</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.label)}<small class="${r.achieved?'good':'warning'}">${esc(r.status)}</small></th><td>${r.science===null?'—':fmt(r.science,1)}</td><td>${r.battery===null?'—':fmt(r.battery,1)+'%'}</td><td>${r.lostMB===null?'—':fmt(r.lostMB,1)+' MB'}</td><td>${fmt(r.cost,1)} cr</td><td>${fmt(r.mass,1)} kg</td></tr>`).join('')}</tbody></table></div>${rows.filter(r=>!r.launchable).map(r=>`<p class="warning">${esc(r.label)}: ${r.warnings.filter(w=>w.status==='fail').map(w=>esc(w.name+': '+w.value)).join('; ')}</p>`).join('')}`;}
function answerCard(a,index){
 const locked=!!(state.run&&!state.run.done),bn=state.prefs.language==='bn';
 return `<article class="assistant-answer ${a.known?'':'uncertain'}">${a.evidence?`<span class="copilot-evidence">${esc(a.evidence)}</span>`:''}<strong>${esc(a.title)}</strong><p>${esc(a.text).replaceAll('\n','<br>')}</p>${a.comparisons?comparisonTable(a.comparisons):''}${a.proposal?`<button class="btn primary small" data-assistant-apply="${index}" ${locked?'disabled':''}>${bn?'Draft-এ প্রয়োগ করুন':'Apply to draft'} · ${esc(a.proposal.label)}</button><small class="copilot-apply-note">${locked?'Hardware is locked until this flight ends.':bn?'শুধু design বদলাবে; launch হবে না।':'Changes the design only; does not launch.'}</small>`:''}${a.sources.map(x=>`<a href="${x.url}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a>`).join(' · ')}<div class="assistant-quick">${a.suggestions.map(q=>`<button class="btn small ghost" data-ask="${esc(q)}">${q}</button>`).join('')}</div></article>`;
}
function askAssistant(q){if(!String(q).trim())return;state.chat.push({q:String(q).slice(0,500),answer:answerQuestion(q,activeContext())});state.chat=state.chat.slice(-12);mentor();$('#assistant-question')?.focus();}
function applyAssistant(index){
 const proposal=state.chat[Number(index)]?.answer?.proposal;
 if(!proposal||state.run&&!state.run.done){toast('Finish the current flight before changing hardware.');return;}
 const current=normalize(state.design);
 if(Object.keys(proposal.base).some(k=>proposal.base[k]!==current[k])){toast('Your design has changed. Preview this experiment again before applying it.');return;}
 state.design=normalize({...current,...proposal.patch});state.robust=null;state.game.stage='hangar';state.page='game';persist();closeModal();render();toast('Draft updated. Review launch readiness before flying.');
}
const QUESTIONS=[{q:'Which observations count toward the mission objective?',opts:['All data the instrument generates','Quality-weighted observations returned to Earth','Everything left in the recorder'],answer:1,why:'The science objective counts useful returned observations. Data onboard may never reach the scientists.'},{q:'Why can a spacecraft with strong solar panels fail in eclipse?',opts:['Solar panels generate no power in shadow; battery energy must carry the loads','The instrument gets heavier in eclipse','Communication consumes propellant automatically'],answer:0,why:'Power is a rate (W). A battery stores energy (Wh). Enough solar power in daylight does not guarantee enough stored energy for darkness.'},{q:'What does the Educational Robustness Index mean?',opts:['The real probability NASA will approve the mission','The modeled fraction meeting the objective under stated parameter variations','The percentage of hardware that cannot fail'],answer:1,why:'It is a sensitivity result for this simplified model and recovery policy, not a validated real-world reliability estimate.'}];
function quiz(){if(!state.quiz)state.quiz={i:0,answers:[]};const qz=state.quiz,q=QUESTIONS[qz.i];modal(`<div class="modal-top"><div><div class="eyebrow">LEARNING CHECK / ${qz.i+1} OF 3</div><h2 style="margin-top:8px">Think like an engineer.</h2></div>${button('Close ×','close','ghost small')}</div><p style="color:var(--text);font-size:16px">${q.q}</p>${q.opts.map((t,i)=>`<button class="quiz-option ${qz.answers[qz.i]===undefined?'':i===q.answer?'correct':qz.answers[qz.i]===i?'incorrect':''}" data-answer="${i}" ${qz.answers[qz.i]!==undefined?'disabled':''}>${t}</button>`).join('')}${qz.answers[qz.i]!==undefined?`<p class="${qz.answers[qz.i]===q.answer?'good':'warning'}">${q.why}</p>${qz.i<2?button('Next question ↗','next-question','primary'): `<div class="notice">${qz.answers.filter((x,i)=>x===QUESTIONS[i].answer).length} / 3 correct. This is a self-check, not a validated measure of educational impact.</div>${button('Finish','close','primary')}`}`:''}`);}
function showSceneFallback(){const box=$('#game-canvas');if(box)box.outerHTML=`<div class="game-fallback">${scene({running:state.playing,eclipse:state.run?.eclipse,contact:state.run?.contact})}<span class="badge">2D FALLBACK · GAMEPLAY FULLY AVAILABLE</span></div>`;}
function game(){const stage=state.game.stage;
  if(stage==='report'&&state.run?.done)return gameReport();
  const flying=stage==='flight'&&state.run&&!state.run.done,s=flying?state.run:null,a=calculate(s?.design||state.design),cat=state.category;
  return `<div class="game-heading"><div><span class="eyebrow">${flying?'LP-01 / LIVE MISSION':'LP-01 / SPACECRAFT HANGAR'}</span><h1>${flying?'You have the controls.':'Build your way to the Moon.'}</h1></div><div class="button-group">${button('Ask assistant','mentor','ghost small')}${button('How to play','game-help','ghost small')}${button('Customize','customize','ghost small',flying?'disabled':'')}${button('Focus view ⛶','focus','ghost small')}${button('Sources','game-sources','ghost small')}</div></div>
  <div class="game-objective"><div><span class="mission-symbol">◈</span><strong>${esc(a.d.name)}</strong><span>Return ≥520 / 650 target science units · stay within 150 credits</span></div><div class="objective-meter"><span>${s?fmt(s.science):'0'} / 650 SCIENCE</span><div class="bar"><i style="width:${s?clamp(s.science/650*100,0,100):0}%"></i></div></div></div>
  ${coachStrip(a,s)}${flying?orbitTimeline(a,s):''}<div class="game-layout"><aside class="game-inventory panel"><div class="game-panel-heading"><span class="kicker">${flying?'FLIGHT ARCHITECTURE':'ASSEMBLY BAY'}</span><span class="badge">${flying?'LOCKED':'DRAG OR SELECT'}</span></div>${flying?flightInventory(a,s):`<div class="game-category-list">${CATEGORIES.map(([k,t],i)=>`<button data-category="${k}" class="game-category ${k===cat?'selected':''}"><span class="slot-icon">${['▧','◉','☀','▴','⌁','▥','↑'][i]}</span>${t}<span class="slot-check">✓</span></button>`).join('')}</div><div class="game-module-list"><span class="kicker">${CATEGORIES.find(x=>x[0]===cat)[2]}</span>${CATALOG[cat].map(c=>`<button class="game-module ${c.id===state.design[cat]?'installed':''}" draggable="true" data-component="${c.id}" data-kind="${cat}" data-dragmodule="${c.id}" data-dragkind="${cat}" aria-pressed="${c.id===state.design[cat]}"><div><strong>${c.name}</strong><span>${c.id===state.design[cat]?'INSTALLED':'INSTALL →'}</span></div><p>${c.note}</p><div class="module-numbers"><span>${c.mass} kg</span><span>${c.cost} cr</span><span>${c.power} W load</span></div></button>`).join('')}</div><small class="game-assumption">Fictional teaching hardware. Drag a module onto the spacecraft, or select it here.</small>`}</aside>
  <section class="game-world panel" aria-label="Interactive mission scene"><div class="world-top"><span class="badge">${flying?s.phase.toUpperCase():'ASSEMBLY / 3D SCHEMATIC'}</span><span class="world-state ${s?.safe?'warning':''}">${s?s.safe?'SAFE MODE':s.eclipse?'IN ECLIPSE':s.contact?'CONTACT WINDOW':'SUNLIGHT':'LP-01 · READY FOR YOUR DESIGN'}</span></div><canvas id="game-canvas" tabindex="0" aria-label="Interactive 3D spacecraft scene. Drag to rotate, scroll to zoom, arrow keys rotate. In the hangar, click a spacecraft subsystem to select it."></canvas><div class="world-bottom"><span>${flying?`${s.design.altitude} km · ${s.design.inclination}° inclination · ${fmt(a.period,1)} min period`:'DRAG TO ROTATE · SCROLL TO ZOOM · CLICK MODULES'}</span>${button('Reset camera','camera-reset','ghost small')}</div>${!flying?`<div class="spacecraft-slots" aria-label="Clickable spacecraft subsystem slots">${CATEGORIES.filter(([k])=>k!=='launch').map(([k,t])=>`<button data-category="${k}" class="${k===cat?'active':''}">${t.split(' ')[0]} <span>✓</span></button>`).join('')}</div>`:''}${s?.crisis?`<div class="game-crisis">${crisisCard(s.crisis)}</div>`:''}${stage==='brief'?gameBriefOverlay():''}</section>
  <aside class="game-resources panel"><div class="game-panel-heading"><span class="kicker">${flying?'LIVE TELEMETRY':'MISSION CONSTRAINTS'}</span><span class="badge">ENGINE</span></div>${flying?gameTelemetry(a,s):gameMargins(a)}${flying?`<div class="game-clock"><span class="kicker">CAMPAIGN CLOCK</span><strong>T+${fmt(s.minute,1)} <small>min</small></strong><div class="bar"><i style="width:${s.minute/240*100}%"></i></div></div>`:`<div class="game-orbit"><label for="game-fuel">Propellant <strong>${state.design.fuel} kg</strong></label><input type="range" id="game-fuel" min="0" max="${a.c.propulsion.maxFuel}" value="${state.design.fuel}" data-gamefield="fuel"><label for="game-altitude">Orbit altitude <strong>${state.design.altitude} km</strong></label><input type="range" id="game-altitude" min="50" max="200" step="10" value="${state.design.altitude}" data-gamefield="altitude"><label for="game-inclination">Inclination</label><select id="game-inclination" data-gamefield="inclination"><option value="90" ${state.design.inclination===90?'selected':''}>90° · Polar</option><option value="60" ${state.design.inclination===60?'selected':''}>60° · Mid-inclination</option><option value="30" ${state.design.inclination===30?'selected':''}>30° · Low-inclination</option></select></div>${button('Launch readiness →','game-review','primary game-launch',stage==='brief'?'disabled':'')}`}</aside></div>
  ${flying?gameOperations(s):`<div class="game-assembly-footer"><div><strong>DESIGN CHOICE → MISSION CONSEQUENCE</strong><p>Click the spacecraft to inspect a subsystem. Every installed class changes the engineering model.</p></div><div class="button-group">${button('Balanced build','preset-balanced','small ghost')}${button('High-science challenge','preset-fragile','small ghost')}${button('Engineering detail','architect','small ghost')}</div></div>`}
  ${flying?`<div class="game-log">${s.logs.slice(-3).reverse().map(l=>`<div><span>T+${fmt(l.minute,1)}</span><strong class="${l.type==='warning'?'warning':''}">${l.title}</strong><p>${l.detail}</p></div>`).join('')}</div>`:''}`;
}
function gameBriefOverlay(){return `<div class="game-brief-overlay"><div class="eyebrow">MISSION OFFER / LP-01</div><h2>Your first mission<br>starts here.</h2><p>You are building a robot to map the Moon. Choose its parts, launch, and bring its observations back to Earth.</p><ol class="beginner-steps"><li><strong>Build:</strong> choose parts within 150 credits.</li><li><strong>Fly:</strong> protect the battery and return data.</li><li><strong>Learn:</strong> reach 520 science units, then improve.</li></ol><div class="brief-tokens"><span>No space knowledge needed</span><span>Free · offline-ready</span></div>${button('Accept mission · enter hangar','game-accept','primary')}${button('Explain in বাংলা / English','mentor','ghost small')}<small>Your Balanced spacecraft is ready. You can change one part at a time.</small></div>`;}
function flightInventory(a,s){return `<div class="flight-loadout">${CATEGORIES.map(([k,t])=>`<div><span>${t}</span><strong>${a.c[k].name}</strong></div>`).join('')}</div><div class="flight-design-warning">Hardware is locked after launch. Your recovery options depend on the spacecraft you built.</div>${button('Why this state?','mentor','ghost small')}`;}
function gameMargins(a){const rows=[['MASS',a.wet,a.c.launch.capacity,'kg',a.margins.mass,`${fmt(a.margins.mass,1)} kg margin`],['COST',a.cost,150,'cr',a.margins.budget,`${a.margins.budget} credits remaining`],['Δv',a.deltaV,750,'m/s',a.margins.deltaV,`${fmt(a.margins.deltaV)} m/s reserve margin`],['ECLIPSE',a.eclipseEnergy,a.usableBattery,'Wh',a.margins.eclipse,`${fmt(a.margins.eclipse,1)} Wh energy reserve`]];return `<div id="game-margin-values">${rows.map(([title,v,max,unit,m,desc])=>`<div class="game-gauge" title="Educational first-order model; ${desc}"><div><span>${title}</span><strong class="${m<0?'warning':'good'}">${fmt(v)} <small>${unit}</small></strong></div><div class="bar"><i class="${m<0?'warn':''}" style="width:${clamp(v/max*100,3,100)}%"></i></div><small>${desc}</small></div>`).join('')}<div class="game-contact-budget"><span>POWER MARGIN <b class="${a.margins.power<0?'warning':'good'}">${fmt(a.margins.power)} W</b></span><span>CONTACT MARGIN <b class="${a.margins.data<0?'warning':'good'}">${fmt(a.margins.data)} MB/orbit</b></span><span>POINTING <b>${a.c.bus.pointing}″ / ${a.c.payload.pointingMax}″</b></span></div></div>`;}
function gameTelemetry(a,s){return [['BATTERY',s.battery,a.c.power.battery,'Wh',s.battery/a.c.power.battery<.3],['RECORDER',s.backlog,a.c.storage.capacity,'MB',s.backlog/a.c.storage.capacity>.75],['RETURNED SCIENCE',s.science,650,'units',false],['PROPELLANT',s.fuel,s.design.fuel,'kg',false]].map(([label,v,max,unit,warn])=>`<div class="game-gauge"><div><span>${label}</span><strong class="${warn?'warning':'cyan'}">${fmt(v,unit==='Wh'||unit==='kg'?1:0)} <small>${unit}</small></strong></div><div class="bar"><i class="${warn?'warn':''}" style="width:${clamp(v/Math.max(1,max)*100,0,100)}%"></i></div><small>${fmt(v/Math.max(1,max)*100)}% of ${fmt(max)} ${unit}${label==='RETURNED SCIENCE'?' · objective at 80%':''}</small></div>`).join('')+`<div class="game-contact-budget"><span>LOST DATA <b>${fmt(s.lostMB)} MB</b></span><span>SAFE MODE <b>${fmt(s.safeSteps*5,1)} min</b></span><span>LINK <b>${s.contact?'IN CONTACT':'OUT OF CONTACT'}</b></span></div>`;}
function gameOperations(s){return `<section class="game-commands panel"><div class="command-heading"><span class="eyebrow">COMMAND THE SPACECRAFT</span><p>${s.crisis?'Choose a crisis response above. Commands unlock afterwards.':s.phase==='operations'?'Your schedule changes energy use, data generation and science return.':'The provider injects the trajectory. Capture depends on your propellant reserve.'}</p></div><div class="operation-choices">${[['science','◉','Map in sunlight','Pause science in eclipse'],['aggressive','✦','Map through shadow','More observations, more load'],['coast','☀','Conserve energy','Pause science and transmitter'],['downlink','⌁','Return priority','Collect less; drain on contact']].map(([id,symbol,title,detail])=>`<button class="operation-choice ${s.mode===id?'active':''}" data-command="${id}" ${s.crisis||s.phase!=='operations'?'disabled':''}><span>${symbol}</span><div><strong>${title}</strong><small>${detail}</small></div></button>`).join('')}</div><div class="game-play-controls"><div class="button-group">${button(state.playing?'Ⅱ Pause':'▶ Resume','play','primary',s.crisis?'disabled':'')}${button('+5 min / next phase','step','ghost',s.crisis?'disabled':'')}${button('Next event ⇥','fast','ghost',s.crisis?'disabled':'')}</div><div class="button-group">${[1,3,10].map(n=>button(`${n}×`,`speed-${n}`,`small ${state.speed===n?'':'ghost'}`)).join('')}${button('Battery timeline','game-history','small ghost')}</div></div></section>`;}
function gameReport(){const s=state.run,o=s.outcome,d=debrief(s),previous=state.runs.filter(r=>r.id!==s.id).at(-1);return `${heading('MISSION COMPLETE / '+s.label,o.achieved?'You brought the science home.':'Your mission has a lesson.','The result follows from your spacecraft and operational decisions.',`${button('Export mission','export','ghost small')}${button('Redesign & play again →','game-redesign','primary')}`)}<div class="game-result panel"><div class="completion-ring" style="--p:${o.completion}"><div class="ring-inner"><strong>${fmt(o.completion)}%</strong><span>SCIENCE RETURN</span></div></div><div><div class="eyebrow ${o.achieved?'good':'warning'}">${o.achieved?'OBJECTIVE ACHIEVED':'OBJECTIVE INCOMPLETE'}</div><h2>${fmt(o.science)} / 650 science units</h2><p>Return threshold: 520 units. Cost: ${o.cost} / 150 credits. ${fmt(o.safeMinutes,1)} minutes in safe mode.</p></div><div class="result-evidence"><span>${fmt(o.returned)} MB returned</span><span>${fmt(o.retainedMB)} MB left onboard</span><span>${fmt(o.lostMB)} MB discarded</span></div></div><div class="two-col"><div class="stack"><h3>Here is why it happened</h3>${d.items.length?d.items.map(e=>`<div class="panel cause-card"><h3>${e.title}</h3>${chain(e.chain)}<p>${e.impact}</p><div class="recovery">YOUR DECISION / ${e.action}</div></div>`).join(''):`<div class="panel cause-card">${chain(['Compatible spacecraft','Power and contact capacity sustained operations','Science reached Earth'])}<p>No crisis threshold was crossed. Try reducing the cost to explore the margin trade-off.</p></div>`}</div><div class="stack"><div class="panel panel-pad"><h3>Change the design. Test the result.</h3><div style="margin:20px 0">${d.tips.map(t=>`<div class="tip"><span>↗</span>${t}</div>`).join('')}</div>${button('Try the resilient preset','game-fix','primary')}<p style="font-size:11px;margin-top:15px">Loads the complete resilient preset. Use your own redesign to change only one variable.</p></div><div class="panel panel-pad"><h3>Your redesign evidence</h3>${previous?comparison(previous,s):'<p style="margin-top:15px;font-size:12px">Play a second mission. Its result will be compared against this run.</p>'}</div><div class="button-group">${button('Trade-space plot','trade','ghost')}${button('Learning check','quiz','ghost')}${button('Detailed debrief','game-debrief','ghost')}</div></div></div>`;}
function gameReview(){const a=calculate(state.design);modal(`<div class="modal-top"><div><div class="eyebrow">PRE-LAUNCH CHECK</div><h2 style="margin-top:8px">Commit your design?</h2></div>${button('Back to hangar ×','close','ghost small')}</div><div class="check-list">${a.checks.map(c=>`<div class="check-row"><span class="status ${c.status}">${c.status.toUpperCase()}</span><div><h3>${c.name}</h3><p>${c.why}</p></div><span class="check-value">${c.value}</span></div>`).join('')}</div><p>${a.launchable?'Hardware is locked after launch. Warnings become operational consequences. You can recover only using the capabilities you selected.':'Resolve the hard failures in the hangar. Impossible mass, budget or interfaces cannot launch.'}</p>${button('Authorize launch · enter flight →','game-launch','primary',!a.launchable?'disabled':'')}`);}
function gameHelp(){modal(`<div class="modal-top"><div><div class="eyebrow">PLAYER GUIDE</div><h2 style="margin-top:8px">Design. Command. Learn.</h2></div>${button('Close ×','close','ghost small')}</div><div class="mentor-fact"><h3>1 · Build in the hangar</h3><p>Click a spacecraft subsystem, choose a module or drag one onto the 3D view. Drag the view to rotate, scroll to zoom, and adjust fuel and orbit. Watch the margins.</p></div><div class="mentor-fact"><h3>2 · Accept your trade-offs</h3><p>Open Launch readiness. Hard failures block launch. Advisory warnings are allowed, but their consequences will appear during flight.</p></div><div class="mentor-fact"><h3>3 · Operate the mission</h3><p>Map in sunlight or shadow, conserve energy, or prioritize returning data. Pause or step the clock. Next event advances until a decision or the campaign end.</p></div><div class="mentor-fact"><h3>4 · Respond, then redesign</h3><p>Crises pause automatically. Choose an available response, inspect the causal report and replay with a changed spacecraft. Only returned science counts.</p></div><p>Keyboard in the 3D view: arrows rotate, + / − zoom, R resets the camera. Touch: drag to rotate. The scene is a schematic, not a flight trajectory to scale.</p>`);}
const actions={'clear-chat':()=>{state.chat=[];mentor();},'export-nasa':()=>{const rows=[['parameter','value','unit','source_url','verified_utc'],...NASA_DATA.rows.map(r=>[r.id,r.value,r.unit,r.source==='jpl'?NASA_DATA.jplURL:NASA_DATA.factURL,NASA_DATA.verified])];const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(x=>JSON.stringify(String(x))).join(',')).join('\n')],{type:'text/csv'}));const el=document.createElement('a');el.href=url;el.download='TRAJECTIQ_NASA_Moon_Data.csv';el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},customize,mentor,'nasa-data':()=>modal(`<div class="modal-top"><h2>NASA data used in your mission</h2>${button('Close','close','ghost small')}</div>${nasaPanel()}`),'guide-next':()=>{state.guide=Math.min(3,state.guide+1);render();},'guide-toggle':()=>{state.prefs.guided=!state.prefs.guided;persist();render();},'apply-custom':()=>{closeModal();render();toast('Customization saved. Mass, power, data and cost updated.');},home:()=>go('landing'),start:()=>{pause();state.game.stage='brief';state.run=null;go('game');},brief:()=>go('brief'),architect:()=>go('architect'),readiness:()=>go('readiness'),trade:()=>go('trade'),pitch:()=>{state.pitch=true;state.page='game';preset('fragile');},'exit-pitch':()=>{state.pitch=false;render();},launch,play:()=>state.playing?(pause(),render()):play(),step:()=>{pause();tick();},fast,robust:()=>{toast('Sampling 200 deterministic uncertainty cases…');setTimeout(()=>{state.robust=robustness(state.design);render();toast('Sample complete. This is a model sensitivity result.');},50);},mentor,close:closeModal,export:exportReport,redesign:()=>{const r=state.run?.done?state.run:state.runs.at(-1);if(r)state.design=normalize(r.design);state.robust=null;persist();go('architect');},quiz:()=>{state.quiz=null;quiz();},'next-question':()=>{state.quiz.i++;quiz();},'clear-history':()=>modal(`<div class="modal-top"><h2>Clear saved mission runs?</h2>${button('Close ×','close','small ghost')}</div><p>This removes the local comparison archive. Your current spacecraft design remains available.</p>${button('Clear history','confirm-clear','danger')}`),'confirm-clear':()=>{state.runs=[];persist();closeModal();render();},'game-accept':()=>{state.game.stage='hangar';state.guide=0;render();},'game-review':gameReview,'game-launch':()=>{closeModal();launch();},'game-help':gameHelp,'game-sources':()=>go('sources'),'game-history':()=>modal(`<div class="modal-top"><h2>Battery history</h2>${button('Close ×','close','small ghost')}</div>${sparkline(state.run?.history||[])}<p>At most one-minute physics intervals, split at shadow/contact boundaries. +5 min stops early at a crisis. The dashed line marks the 15% safe-mode threshold.</p>`),'camera-reset':()=>{cameraState.yaw=.65;cameraState.pitch=.28;cameraState.distance=7;toast('Camera reset.');},focus:()=>{state.game.fullscreen=!state.game.fullscreen;render();},'game-redesign':()=>{state.design=normalize(state.run.design);state.game.stage='hangar';state.robust=null;persist();go('game');},'game-fix':()=>{state.page='game';preset('resilient');},'game-debrief':()=>go('debrief')};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-page],[data-category],[data-component],[data-recovery],[data-loadrun],[data-answer],[data-command],[data-ask],[data-assistant-apply]');if(!b)return;e.preventDefault();if(b.disabled)return;
  if(b.dataset.assistantApply!==undefined){applyAssistant(b.dataset.assistantApply);return;}
  if(b.dataset.ask){askAssistant(b.dataset.ask);return;}
  if(b.dataset.action){const act=b.dataset.action;if(act.startsWith('preset-'))preset(act.slice(7));else if(act.startsWith('speed-')){state.speed=Number(act.slice(6));if(state.playing)play();else render();}else actions[act]?.();}
  else if(b.dataset.page)go(b.dataset.page);
  else if(b.dataset.category){state.category=b.dataset.category;render();}
  else if(b.dataset.component){if(!CATALOG[b.dataset.kind]?.some(c=>c.id===b.dataset.component))return;state.design[b.dataset.kind]=b.dataset.component;state.design=normalize(state.design);state.robust=null;persist();render();}
  else if(b.dataset.recovery){try{state.run=resolve(state.run,b.dataset.recovery);if(state.run.done)finishUI();else{pause();render();toast('Decision applied. Review your spacecraft, then Resume.');}}catch(err){toast(err.message);}}
  else if(b.dataset.loadrun){pause();state.run=clone(state.runs.find(r=>r.id===b.dataset.loadrun));go('debrief');}
  else if(b.dataset.answer){state.quiz.answers[state.quiz.i]=Number(b.dataset.answer);quiz();}
  else if(b.dataset.command&&state.run&&!state.run.crisis){state.run.mode=b.dataset.command;state.run.autoResume=false;state.run.logs.push({minute:state.run.minute,type:'decision',title:`Operations: ${b.dataset.command}`,detail:'Player changed the science/energy/downlink schedule.'});render();}
});
document.addEventListener('input',e=>{const gf=e.target.dataset.gamefield;if(gf){state.design[gf]=Number(e.target.value);state.design=normalize(state.design);state.robust=null;const value=e.target.previousElementSibling?.querySelector('strong');if(value)value.textContent=`${e.target.value} ${gf==='fuel'?'kg':'km'}`;const rails=$('#game-margin-values');if(rails)rails.outerHTML=gameMargins(calculate(state.design));persist();return;}const f=e.target.dataset.field;if(f==='fuel'||f==='altitude'){state.design[f]=Number(e.target.value);state.robust=null;e.target.closest('.slider-field').querySelector('strong').textContent=`${e.target.value} ${f==='fuel'?'kg':'km'}`;const rail=$('.margin-rail');if(rail)rail.outerHTML=marginRail(calculate(state.design));persist();}});
document.addEventListener('change',e=>{if(e.target.id==='experiment-part'&&e.target.value){askAssistant(e.target.value);return;}if(e.target.id==='experiment-field'){const f=EXPERIMENT_FIELDS.find(x=>x[0]===e.target.value);if(f){const d=calculate(activeContext().run?.design||state.design);const input=$('#experiment-value');input.value=d.d[f[0]];input.min=f[2];input.max=f[0]==='fuel'?d.c.propulsion.maxFuel:f[3];$('#experiment-range').textContent=f[1]+': '+input.min+'–'+input.max;}return;}if(e.target.dataset.pref){const k=e.target.dataset.pref;if(k==='language')state.prefs.language=e.target.value==='bn'?'bn':'en';else if(k==='guided'||k==='reducedMotion')state.prefs[k]=e.target.checked;persist();render();if(k==='language')mentor();return;}if(e.target.dataset.custom){const k=e.target.dataset.custom;if(state.game.stage==='flight'&&state.run&&!state.run.done)return;state.design=normalize({...state.design,[k]:e.target.value});state.robust=null;persist();const r=$('#custom-summary');if(r)r.innerHTML=customSummary();return;}const gf=e.target.dataset.gamefield;if(gf){state.design[gf]=Number(e.target.value);state.design=normalize(state.design);state.robust=null;persist();render();return;}const f=e.target.dataset.field;if(f==='fuel'||f==='altitude'){state.design[f]=Number(e.target.value);state.design=normalize(state.design);persist();render();}if(f==='inclination'){state.design.inclination=Number(e.target.value);state.robust=null;persist();render();}if(f==='mode'&&state.run&&!state.run.crisis&&!state.run.done){state.run.mode=e.target.value;state.run.autoResume=false;render();}if(f==='mentor-level'){state.mentorLevel=e.target.value;mentor();}});
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-dragmodule]');if(el)e.dataTransfer.setData('application/x-trajectiq',JSON.stringify({kind:el.dataset.dragkind,id:el.dataset.dragmodule}));});
document.addEventListener('dragover',e=>{if(e.target.closest('.game-world')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
document.addEventListener('drop',e=>{if(!e.target.closest('.game-world')||state.game.stage!=='hangar')return;e.preventDefault();try{const {kind,id}=JSON.parse(e.dataTransfer.getData('application/x-trajectiq'));if(!CATALOG[kind]?.some(c=>c.id===id))return;state.design[kind]=id;state.design=normalize(state.design);state.category=kind;state.robust=null;persist();render();toast(`${calculate(state.design).c[kind].name} installed. Margins updated.`);}catch{}});
document.addEventListener('submit',e=>{if(e.target.id==='experiment-form'){e.preventDefault();askAssistant('What if '+$('#experiment-field').value+' = '+$('#experiment-value').value);return;}if(e.target.id==='assistant-form'){e.preventDefault();askAssistant($('#assistant-question')?.value||'');}});
document.addEventListener('keydown',e=>{if(!$('#modal-root').firstChild)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=[...$('#modal-root').querySelectorAll('button:not(:disabled),a,select,input,summary,[tabindex="0"]')];const first=els[0],last=els.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
render();
if('serviceWorker' in navigator) navigator.serviceWorker.register('./sw.js').catch(()=>{});

function coachStrip(a,s){
 const bn=state.prefs.language==='bn';
 if(!state.prefs.guided)return `<div class="coach-collapsed">${button(bn?'Guided help চালু করুন':'Show guided help','guide-toggle','ghost small')}</div>`;
 const steps=bn?[
 ['আপনি spacecraft designer','Camera ছবি তোলে, battery শক্তি রাখে, antenna ডেটা পাঠায়। Balanced build দিয়ে শুরু করুন।'],
 ['একটি part বদলে দেখুন','বামে Power system বেছে অন্য kit নিন। ডানদিকে ওজন, খরচ ও battery reserve কীভাবে বদলায় দেখুন।'],
 ['Launch করার আগে পরীক্ষা','Launch readiness চাপুন। FAIL হলে আগে ঠিক করুন। WARN হলে তার পরিণতি বুঝে সিদ্ধান্ত নিন।'],
 ['শুধু পৃথিবীতে ফেরত আসা science গণনা হয়','Map in sunlight দিয়ে শুরু করুন। Storage ভরলে Return priority দিন। Battery কমলে Conserve energy দিন।']
 ]:[
 ['You are the spacecraft designer','The camera observes, the battery stores energy, and the antenna sends data home. Start with the Balanced build.'],
 ['Try one change','Choose Power system on the left, then install another kit. Watch mass, cost and battery reserve change on the right.'],
 ['Check before you launch','Open Launch readiness. Fix red FAIL items. Read amber WARN items and decide whether you can handle their consequences.'],
 ['Bring the science home','Start with Map in sunlight. Use Return priority when storage fills, or Conserve energy when battery is low.']
 ];
 let [title,body]=steps[state.guide];
 if(s){title=s.crisis?(bn?'সিদ্ধান্ত নেওয়ার সময়':'Your decision is needed'):s.safe?'Safe mode protects the spacecraft':s.phase!=='operations'?'Travelling to the Moon':s.mode==='coast'?'Collection is paused':s.contact?'Your antenna can reach Earth':s.eclipse?'The spacecraft is in shadow':'Sunlight is your collection window';body=s.crisis?'The clock is paused. Each response explains what you gain and what you give up. Choose a response, then Resume.':s.safe?'Science and transmission are off until battery rises above 40%. The spacecraft still uses basic platform power.':s.mode==='coast'?`No new science or data transmission. ${s.autoResume?'Mapping resumes automatically in sunlight above 60% battery.':'Switch to Map in sunlight when you are ready to collect again.'}`:s.eclipse?'Solar panels generate no power. The battery must run the spacecraft. Map in sunlight automatically pauses observations here.':s.contact?'Stored data is being sent if your spacecraft has energy. Only useful observations received on Earth increase your score.':'Collect observations now, then send them during the next contact. Watch energy and storage together.';}
 return `<section class="coach-strip" aria-label="Beginner mission coach"><div class="coach-number">${s?'?':state.guide+1}</div><div><strong>${title}</strong><p>${body}</p></div><div class="button-group">${!s&&state.guide<3?button(bn?'পরের নির্দেশনা':'Next hint','guide-next','small primary'):button(bn?'প্রশ্ন করুন':'Ask a question','mentor','small primary')}${button('Hide tips','guide-toggle','small ghost')}</div></section>`;
}
function orbitTimeline(a,s){
 const position=s.minute%a.period,contactStart=a.period-M.eclipseMinutes-M.contactMinutes,eclipseStart=a.period-M.eclipseMinutes;
 const next=position<contactStart?{label:'Ground contact',time:contactStart-position}:position<eclipseStart?{label:'Shadow',time:eclipseStart-position}:{label:'Sunlight',time:a.period-position};
 return `<section class="orbit-timeline panel" aria-label="Orbit timing"><div><strong>${s.phase==='operations'?`${next.label} in ${fmt(next.time,1)} min`:'Campaign clock starts after lunar capture'}</strong><span>${fmt(s.science,1)} returned / 520 to succeed · ${fmt(Math.max(0,240-s.minute),1)} min remaining</span></div><div class="orbit-track"><span style="width:${contactStart/a.period*100}%">Collect in sunlight</span><span class="contact" style="width:${M.contactMinutes/a.period*100}%">Send data</span><span class="shadow" style="width:${M.eclipseMinutes/a.period*100}%">Shadow</span><i style="left:${position/a.period*100}%" title="Current orbit position"></i></div><small>Repeating teaching schedule. Contact and shadow durations are assumptions.</small></section>`;
}
function customSummary(){const a=calculate(state.design),env=linkEnvironment(a.d);return `<div class="custom-metrics"><span>Mass <strong class="${a.margins.mass<0?'warning':''}">${fmt(a.wet,1)} / ${a.c.launch.capacity} kg</strong></span><span>Cost <strong class="${a.margins.budget<0?'warning':''}">${fmt(a.cost,1)} / 150 cr</strong></span><span>Array <strong>${fmt(a.c.power.arrayArea,2)} m² · ${fmt(a.c.power.solar)} W</strong></span><span>Battery <strong>${fmt(a.c.power.battery)} Wh</strong></span><span>Link factor <strong>${fmt(env.factor*100,1)}%</strong></span><span>One-way signal <strong>${fmt(env.delay,3)} s</strong></span></div><p>${a.launchable?'Design can launch. Review advisory warnings before committing.':'This design has a blocking limit. Reduce mass/cost or fix compatibility before launch.'}</p>`;}
function customize(){
 if(state.game.stage==='flight'&&state.run&&!state.run.done){toast('Hardware is locked in flight. Finish the mission, then redesign.');return;}
 const d=state.design;
 const options=(values,current)=>values.map(([v,label])=>`<option value="${v}" ${String(v)===String(current)?'selected':''}>${label}</option>`).join('');
 const select=(key,label,values,note)=>`<label class="custom-field">${label}<select data-custom="${key}">${options(values,d[key])}</select><small>${note}</small></label>`;
 modal(`<div class="modal-top"><div><div class="eyebrow">MAKE IT YOUR MISSION</div><h2>Customize your spacecraft</h2></div>${button('Done','apply-custom','primary small')}</div><p>Changes save as you make them. Your engineering margins update below. Hardware changes affect the mission; name and color are cosmetic.</p><div class="custom-grid"><label class="custom-field">Mission name<input maxlength="40" data-custom="name" value="${esc(d.name)}"><small>Up to 40 characters.</small></label>${select('livery','Spacecraft color',[['gold','Mission gold'],['cyan','Ion cyan'],['coral','Solar coral']],'Changes the 3D spacecraft body.')}${select('arrayScale','Solar array size',[[.75,'Compact · 75%'],[1,'Standard · 100%'],[1.25,'Extended · 125%'],[1.5,'Maximum · 150%']],'More panel area means more sunlight power, mass and cost.')}${select('batteryScale','Battery size',[[.75,'Light · 75%'],[1,'Standard · 100%'],[1.25,'Extra reserve · 125%'],[1.5,'Deep reserve · 150%']],'More energy storage increases mass and cost.')}${select('duty','Instrument duty',[[.25,'25% · conserve'],[.5,'50% · cautious'],[.75,'75% · balanced'],[1,'100% · maximum']],'Scales instrument power, collected data and science together.')}${select('distance','NASA Earth–Moon distance',Object.entries(DISTANCES).map(([k,v])=>[k,v.name+' · '+fmt(v.km)+' km']),'Fixed NASA reference values, not a live ephemeris. Farther means a slower modeled link.')}</div><div id="custom-summary" aria-live="polite">${customSummary()}</div><details><summary>How NASA data affects this design</summary><p>Solar output = 1,361 W/m² × array area × 28% assumed cell efficiency; operations apply an additional 85% derating. Array size and battery size scale their share of power-system mass/cost. Link rate is scaled by (384,400 / distance)² as a teaching approximation; this is not a complete radio link budget. Signal delay is displayed, not imposed on your controls.</p></details><div class="preferences"><label><input type="checkbox" data-pref="guided" ${state.prefs.guided?'checked':''}> Show beginner tips</label><label><input type="checkbox" data-pref="reducedMotion" ${state.prefs.reducedMotion?'checked':''}> Reduce animation</label></div>${button('Save and return to spacecraft','apply-custom','primary')}`);
}
function nasaPanel(){return `<section class="panel nasa-data-panel"><div class="eyebrow">NASA / JPL · VERIFIED ${NASA_DATA.verified}</div><h2>Real inputs. Visible consequences.</h2><p>This offline snapshot contains selected numeric NASA/JPL data. Physical constants and reference distances drive the model. Hardware specifications, contact schedules and scores remain educational assumptions.</p><div class="table-scroll"><table><thead><tr><th>Parameter</th><th>NASA value</th><th>Use in TRAJECTIQ</th></tr></thead><tbody>${NASA_DATA.rows.map(r=>`<tr><td>${r.label}</td><td>${fmt(r.value,3)} ${r.unit}</td><td>${r.use}</td></tr>`).join('')}</tbody></table></div><p><a href="${NASA_DATA.factURL}" target="_blank" rel="noopener noreferrer">NASA Moon Fact Sheet</a> · <a href="${NASA_DATA.jplURL}" target="_blank" rel="noopener noreferrer">NASA/JPL physical parameters</a></p><p>Fact Sheet updated ${NASA_DATA.factSheetUpdated}. Distance scenarios are mean perigee, semimajor axis and mean apogee; they are not a dated Moon-position forecast. Surface gravity and escape speed are reference facts, not values used for spacecraft capture.</p>${button('Export NASA dataset (CSV)','export-nasa','small ghost')}</section>`;}
